구좌·우도 강동우 더불어민주당 제주도당이 제9회 전국동시지방선거 제주도의원 선거 제주시을 지역 2개 선거구 경선 결과를 발표했다. 민주당 제주도당은 23일 오후 5시30분 제주도당사에서 광역의원 2차 경선 결과를 공개하고, 제주시 일도2동 선거구와 구좌읍·우도면 선거구 후보를 확정했다. 일도2동 선거구에서는 오영훈 도정에서 정무부지사를 지낸 김희현 예비후보와 3선에 도전한 현직 박호형 의원이 맞붙은 끝에 박호형 의원이 경선을 통과했다. 현역 의원이 경선 문턱을 넘으면서 본선행 티켓을 거머쥐었다. 구좌읍·우도면 선거구에서는 무소속 출마를 선언한 부지성 예비후보가 빠진 뒤 강동우 예비후보와 원성현 예비후보의 양자 대결 구도로 재편됐고, 강동우 예비후보가 승리했다. 이에 따라 민주당은 이날 제주시을 지역 2개 선거구 경선을 마무리했으며, 24일에는 서귀포시 지역 2개 선거구 경선 결과를 발표할 예정이다. 김영호 기자 김영호 기자 a01074257898@gmail.com 다른기사 보기 저작권자 © 제민일보 무단전재 및 재배포 금지 jQuery( document ).ready(function() { vote.voteCheck( jQuery('#reply-write-btn, .reply-container'), // 폐쇄시 제거할 영역 'S', // 실명제 구분값 '/news/articleView.html' // 리턴URL ); }); 댓글삭제 삭제한 댓글은 다시 복구할 수 없습니다. 그래도 삭제하시겠습니까? 비밀번호 삭제 닫기 기사 댓글 0 댓글 접기 댓글입력 권한이 없습니다. 댓글 내용입력 0 / 400 비회원 로그인 이름 비밀번호 댓글 내용입력 0 / 400 등록 댓글쓰기 계정을 선택하시면 로그인·계정인증을 통해 댓글을 남기실 수 있습니다. 회원 로그인 이름 비밀번호 자동등록방지 var captchaContainer = null; var reCapVal; var loadCaptcha = function() { grecaptcha.render('captcha_container', { 'sitekey' : '6LdspMUZAAAAAIfJS73Hrprm5a-tyqKY1RRkCVOX', 'callback' : function(response) { reCapVal = response; $("#nomember-captcha").val( reCapVal ); }, 'expired-callback': fnGcCallback }); }; var fnGcCallback = function() { grecaptcha.reset(); $('#btn-nomember-write').removeClass('on').trigger('click'); $("#reply-modal").foundation('open'); }; 확인 취소 로그인 옵션 창닫기 reply.parent_idxno = "836651"; // 게시글 번호 reply.captchaEnable = "Y"; // 캡차사용여부 reply.replyAll = ""; // 전체보기 reply.reply_sc_order_by = "I"; // 정렬 reply.reply_page = "1"; // 페이지 $("#reply-write-btn, #reply-write-text").on('click', {reply_parent_idxno:''}, reply.replyWrite); // 댓글쓰기 이벤트 $("#no-member-write").on('click',reply.noMemberCheck); // 비회원 글쓰기 이벤트 $("#btn-nomember-write").on('click', function(){$("#nomember-info").toggle();$(this).toggleClass('on');}); // 비회원 글쓰기 SHOW $(".comments-more-btn").on('click', reply.viewOption); // 댓글옵션보이기 이벤트 $(".reply-delete-btn").on('click', reply.setDeleteOption); // 댓글삭제 이벤트 $(".vote