#AD162866094474.ad-template .col .ad-view { position:relative; } (adsbygoogle = window.adsbygoogle || []).push({}); 공천이 확정된 후보는 ▲영양군수 오도창 현 군수 ▲봉화군수 최기영 경북도당 부위원장 ▲상주시장 안재민 국민의힘 수석부대변인 ▲문경시장 김학홍 전 경북도 행정부지사 ▲의성군수 최유철 전 의성군의회 의장 ▲청송군수 윤경희 현 군수 ▲영덕군수 조주홍 전 국회부의장 선임비서관 ▲울진군수 손병복 현 군수다. 이외에도 ▲경주시장 주낙영 현 시장 ▲영천시장 김병삼 전 영천시 부시장 ▲청도군수 김하수 현 군수 ▲성주군수 정영길 경북도의원 ▲칠곡군수 김재욱 현 군수가 경선에서 승리해 최종 후보로 확정됐다. 영주시장 선거구에서는 송명달 전 해양수산부 차관, 황병직 전 경북도의원이 예비경선을 통과해 본 경선을 치른다. 앞서 도당 공관위는 김병수 전 울릉군수, 배낙호 김천시장, 김장호 구미시장, 조현일 경산시장을 단수 후보로 공천했고, 이날 고령군수에 이남철 현 군수를 단수 추천했다. 중앙 공관위가 결정한 포항시장은 박용선 전 경북도의원이 경선에서 승리, 본선 후보로 확정됐다. 경북 기초단체장 선거구 가운데 유이하게 공천이 결정되지 않은 곳은 안동시장과 예천군수 후보다. 두 선거구는 모두 김형동 국회의원이 당협위원장을 맡고 있다. 안동시장 선거는 권기창 현 안동시장이 재선에 나선 가운데, 권광택 전 경북도의원, 김의승 전 서울시 행정1부시장 등 3명이 공천장을 두고 경쟁 중이다. 예천군수 선거는 김학동 현 예천군수와 도기욱 전 경북도의원, 안병윤 전 부산시 행정부시장이 공천경쟁을 벌이고 있다. var ___BANNER = "ban_1776424271";var ___BANNER = "ban_1776424278";var ___BANNER = "ban_1776243317";var ___BANNER = "ban_1774248858";var ___BANNER = "ban_1774345029";var ___BANNER = "ban_1776243308";var ___BANNER = "ban_1773911373";var ___BANNER = "ban_1776424325";var ___BANNER = "ban_1770280440";var ___BANNER = "ban_1776057534";var ___BANNER = "ban_1776057541";var ___BANNER = "ban_1766554864";var ___BANNER = "ban_1765869848";var ___BANNER = "ban_1764846087";var ___BANNER = "ban_1767167255";var ___BANNER = "ban_1769401326";var ___BANNER = "ban_1770098400";var ___BANNER = "ban_1770098374";var ___BANNER = "ban_1603241861";var ___BANNER = "ban_1776064174";var ___BANNER = "ban_1776064179";var ___BANNER = "ban_1776064177";var ___BANNER = "ban_1776064172";var ___BANNER = "ban_1765782666";var ___BANNER = "ban_1668583167";var ___BANNER = "ban_1603201118"; #AD162927001476.ad-template { margin:auto; position:relative; display:block; clear:both; z-index:1; padding:20px 0 20px 0;}
